<?php
declare(strict_types=1);
function header_view(string $title, ?array $user): void {
    ?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=h($title)?> · Pródigo</title><link rel="stylesheet" href="assets/admin.css?v=abm2"><script src="assets/admin.js?v=abm1" defer></script><script src="assets/abm.js?v=2" defer></script></head><body><header class="topbar"><a class="brand" href="<?=h(url('list'))?>">Pródigo <span>Gestión del catálogo</span></a><?php if ($user): ?><nav><a href="catalogo.php" target="_blank" rel="noopener">Ver catálogo ↗</a><a href="<?=h(url('list'))?>">Piezas</a><a href="<?=h(url('list',['trash'=>1]))?>">Papelera</a><a href="<?=h(url('appearance'))?>">Visualización</a><a href="<?=h(url('demo'))?>">Ejemplos</a><form method="post" action="<?=h(url('logout'))?>"><?=csrf()?><button class="link" type="submit">Salir</button></form></nav><?php endif ?></header><main><?php
    if (!empty($_SESSION['flash'])) { ?><div class="notice success" role="status"><?=h($_SESSION['flash'])?></div><?php unset($_SESSION['flash']); }
}
function footer_view(): void { ?></main><footer>Pródigo · Panel privado</footer></body></html><?php }
function login_view(bool $setup, string $error): void {
    ?><section class="auth card"><p class="eyebrow">Catálogo y gestión</p><h1><?=$setup?'Creá tu cuenta':'Ingresá a Pródigo'?></h1><p><?=$setup?'Esta cuenta te permitirá administrar las piezas y fotografías. Se crea una sola vez desde localhost.':'Usá tu correo y contraseña para acceder al panel.'?></p><?php if ($error): ?><div class="notice error" role="alert"><?=h($error)?></div><?php endif ?><form method="post" action="<?=h(url($setup?'setup':'login'))?>"><?=csrf()?><label>Correo<input type="email" name="email" required autocomplete="username" value="<?=h($_POST['email']??'')?>"></label><label>Contraseña<input type="password" name="password" required <?=$setup?'minlength="12" maxlength="72"':''?> autocomplete="<?=$setup?'new-password':'current-password'?>"></label><?php if ($setup): ?><p class="muted">Elegí una contraseña de al menos 12 caracteres. No hay una contraseña predeterminada.</p><?php endif ?><button class="primary" type="submit"><?=$setup?'Crear cuenta':'Ingresar'?></button></form></section><?php
}
function list_view(string $error): void {
    $q=is_string($_GET['q']??null)?trim($_GET['q']):'';
    $category=(int)($_GET['category']??0); $pub=(string)($_GET['publication']??''); $availability=(string)($_GET['availability']??''); $trash=!empty($_GET['trash']);
    $page=max(1,(int)($_GET['p']??1)); $perPage=24;
    $where=['p.deleted_at IS ' . ($trash?'NOT NULL':'NULL')]; $args=[];
    if ($q!=='') { $where[]='(p.title LIKE ? OR p.code LIKE ?)'; $args[]='%'.$q.'%'; $args[]='%'.$q.'%'; }
    if ($category) { $where[]='EXISTS (SELECT 1 FROM piece_categories pc WHERE pc.piece_id=p.id AND pc.category_id=?)'; $args[]=$category; }
    if (isset(PUBLICATION[$pub])) { $where[]='p.publication_status=?'; $args[]=$pub; }
    if (isset(AVAILABILITY[$availability])) { $where[]='p.availability=?'; $args[]=$availability; }
    $clause=implode(' AND ',$where);
    $total=(int)query('SELECT COUNT(*) FROM pieces p WHERE '.$clause,$args)->fetchColumn();
    $page=min($page,max(1,(int)ceil($total/$perPage))); $offset=($page-1)*$perPage;
    $rows=query('SELECT p.*, c.image_id,(SELECT GROUP_CONCAT(cat.name ORDER BY cat.position SEPARATOR ", ") FROM piece_categories pc JOIN categories cat ON cat.id=pc.category_id WHERE pc.piece_id=p.id) AS category_names FROM pieces p LEFT JOIN piece_cover c ON c.piece_id=p.id WHERE '.$clause." ORDER BY p.id DESC LIMIT $perPage OFFSET $offset",$args)->fetchAll();
    $categories=query('SELECT * FROM categories ORDER BY position,name')->fetchAll();
    $_SESSION['list_params']=['q'=>$q,'category'=>$category,'publication'=>$pub,'availability'=>$availability,'trash'=>$trash?1:0,'p'=>$page];
    ?><div class="page-heading"><div><p class="eyebrow">Tu catálogo</p><h1><?=$trash?'Papelera':'Piezas'?></h1><p class="muted"><?=$total?> <?=$total===1?'pieza':'piezas'?></p></div><?php if (!$trash): ?><a class="button primary" href="<?=h(url('edit'))?>">+ Nueva pieza</a><?php endif ?></div><?php if ($error): ?><div class="notice error" role="alert"><?=h($error)?></div><?php endif ?>
    <form class="filters card" method="get"><input type="hidden" name="page" value="list"><?php if ($trash): ?><input type="hidden" name="trash" value="1"><?php endif ?><label>Buscar<input name="q" value="<?=h($q)?>" placeholder="Título o código"></label><label>Categoría<select name="category"><option value="">Todas</option><?php foreach ($categories as $cat): ?><option value="<?=$cat['id']?>" <?=$category===$cat['id']||$category===(int)$cat['id']?'selected':''?>><?=h($cat['name'])?></option><?php endforeach ?></select></label><label>Publicación<select name="publication"><option value="">Todos los estados</option><?php foreach (PUBLICATION as $key=>$label): ?><option value="<?=$key?>" <?=$pub===$key?'selected':''?>><?=$label?></option><?php endforeach ?></select></label><label>Disponibilidad<select name="availability"><option value="">Todas</option><?php foreach (AVAILABILITY as $key=>$label): ?><option value="<?=$key?>" <?=$availability===$key?'selected':''?>><?=$label?></option><?php endforeach ?></select></label><button type="submit">Filtrar</button><a href="<?=h(url('list',$trash?['trash'=>1]:[]))?>">Limpiar</a></form>
    <?php if (!$rows): ?><section class="empty card"><h2><?=$q||$category||$pub||$availability?'No hay coincidencias':($trash?'La papelera está vacía':'Tu catálogo comienza acá')?></h2><p><?=$trash?'Las piezas que envíes a papelera se podrán restaurar.':'Creá una ficha y subí las primeras fotos. Podés completar los datos de a poco.'?></p></section><?php else: ?><div class="piece-grid"><?php foreach ($rows as $piece): ?><article class="piece-card card"><?php if ($piece['image_id']): ?><img class="thumbnail" loading="lazy" src="<?=h(url('media',['id'=>$piece['image_id'],'variant'=>'thumbnail']))?>" alt="<?=h($piece['title'])?>"><?php else: ?><div class="thumbnail placeholder">Sin fotografía</div><?php endif ?><div class="piece-content"><span class="code"><?=h($piece['code'])?></span><h2><a href="<?=h(url('edit',['id'=>$piece['id']]))?>"><?=h($piece['title'])?></a></h2><p class="muted"><?=h($piece['category_names'])?></p><div class="badges"><span class="badge"><?=PUBLICATION[$piece['publication_status']]?></span><span class="badge <?=$piece['availability']?>"><?=AVAILABILITY[$piece['availability']]?></span></div><?php if ($trash): ?><form method="post" action="<?=h(url('restore',['id'=>$piece['id']]))?>"><?=csrf()?><button>Restaurar</button></form><?php else: ?><a class="button" href="<?=h(url('edit',['id'=>$piece['id']]))?>">Editar ficha</a><?php endif ?></div></article><?php endforeach ?></div><?php endif ?>
    <?php if ($total>$perPage): ?><nav class="pagination" aria-label="Páginas"><?php if ($page>1): ?><a class="button" href="<?=h(url('list',array_replace($_SESSION['list_params'],['p'=>$page-1])))?>">Anterior</a><?php endif ?><span>Página <?=$page?> de <?=(int)ceil($total/$perPage)?></span><?php if ($page*$perPage<$total): ?><a class="button" href="<?=h(url('list',array_replace($_SESSION['list_params'],['p'=>$page+1])))?>">Siguiente</a><?php endif ?></nav><?php endif ?><?php
}
function form_value(string $key, array $piece): string {
    return h(is_string($_POST[$key]??null)?$_POST[$key]:($piece[$key]??''));
}
function select_view(string $name,string $label,array $choices,array $piece,string $default): void {
    $value=is_string($_POST[$name]??null)?$_POST[$name]:($piece[$name]??$default);
    ?><label><?=h($label)?><select name="<?=h($name)?>" id="<?=h($name)?>"><?php foreach ($choices as $key=>$text): ?><option value="<?=h($key)?>" <?=$value===$key?'selected':''?>><?=h($text)?></option><?php endforeach ?></select></label><?php
}
function edit_view(int $id,string $error): void {
    // El contexto del listado se conserva mientras se abre y se cierra la ficha.
    $params=$_SESSION['list_params']??[];
    $original=$_GET;
    $_GET=['page'=>'list']+$params;
    ob_start(); list_view(''); $background=ob_get_clean();
    $_GET=$original;
    echo '<div class="editor-background" aria-hidden="true">'.$background.'</div>';
    ?><div class="editor-shell" data-return-url="<?=h(url('list',$params))?>"><button type="button" class="editor-close" data-editor-cancel aria-label="Cerrar ficha">×</button><?php edit_form_view($id,$error); ?></div><?php
}
function edit_form_view(int $id,string $error): void {
    $piece=$id?get_piece($id):[]; $images=$id?piece_images($id):[]; $trashed=!empty($piece['deleted_at']);
    $categories=query('SELECT * FROM categories ORDER BY position,name')->fetchAll();
    $chosen=$id?array_column(query('SELECT category_id FROM piece_categories WHERE piece_id=?',[$id])->fetchAll(),'category_id'):[];
    if(!$id&&!empty($_GET['repeat'])) $chosen=$_SESSION['last_categories']??[];
    if (isset($_POST['categories']) && is_array($_POST['categories'])) $chosen=$_POST['categories'];
    $fields=query('SELECT * FROM category_fields ORDER BY position,label')->fetchAll(); $values=[];
    if ($id) foreach (query('SELECT * FROM piece_field_values WHERE piece_id=?',[$id])->fetchAll() as $v) $values[$v['category_id']][$v['field_key']]=$v['value_text'];
    ?><div class="page-heading"><div><a class="back" href="<?=h(url('list',$_SESSION['list_params']??[]))?>">← Volver al listado</a><h1 id="editor-title"><?=$id?h($piece['title']):'Nueva pieza'?></h1><span class="code"><?=$id?h($piece['code']):'El código se asignará al guardar'?></span></div><?php if ($id&&!$trashed): ?><a class="button" href="<?=h(url('preview',['id'=>$id]))?>" target="_blank" rel="noopener">Previsualizar</a><a class="button" href="<?=h(url('appearance',['id'=>$id]))?>">Visualización</a><?php endif ?></div>
    <?php if ($error): ?><div class="notice error" role="alert"><?=h($error)?><?php if (!empty($_FILES['photos']['name'][0])): ?><p>Volvé a seleccionar las fotos antes de guardar.</p><?php endif ?></div><?php endif ?>
    <?php if ($trashed): ?><section class="card"><h2>Esta pieza está en papelera</h2><p>Restaurala para editar su ficha.</p><form method="post" action="<?=h(url('restore',['id'=>$id]))?>"><?=csrf()?><button class="primary">Restaurar pieza</button></form></section><?php return; endif ?>
    <form id="piece-form" class="editor" method="post" enctype="multipart/form-data" action="<?=h(url('edit',['id'=>$id]))?>"><?=csrf()?><?php foreach((is_array($_POST['remove_images']??null)?$_POST['remove_images']:[]) as $removedId): ?><input type="hidden" name="remove_images[]" value="<?=(int)$removedId?>"><?php endforeach ?><input type="hidden" name="_step" value="<?=h(is_string($_POST['_step']??null)?$_POST['_step']:'identity')?>"><input type="hidden" name="version" value="<?=h($_POST['version']??($id?piece_version($id):''))?>"><section class="card" data-step="identity" data-step-title="Identificación"><h2>Identificación</h2><label>Título<input name="title" maxlength="255" value="<?=form_value('title',$piece)?>" placeholder="Un título breve para reconocer la pieza"></label><div class="field-grid"><?php select_view('unit_type','Unidad',['object'=>'Pieza individual','set'=>'Conjunto'],$piece,'object'); ?><label>Cantidad de componentes<input type="number" name="component_count" min="1" max="1000000" value="<?=form_value('component_count',$piece)?>"><small>Opcional, para conjuntos.</small></label></div><fieldset><legend>Categorías</legend><div class="checks"><?php foreach ($categories as $cat): if (!$cat['active']&&!in_array($cat['id'],$chosen)) continue; ?><label><input type="checkbox" name="categories[]" value="<?=$cat['id']?>" <?=in_array($cat['id'],$chosen)?'checked':''?> data-category><?=h($cat['name'])?><?=$cat['active']?'':' (inactiva)'?></label><?php endforeach ?></div></fieldset></section><section class="card" data-step="description" data-step-title="Descripción y datación"><h2>Descripción y datación</h2><label>Descripción<textarea name="description" rows="5" maxlength="10000"><?=form_value('description',$piece)?></textarea></label><div class="field-grid"><label>Datación<input name="dating_label" maxlength="255" placeholder="Ej.: hacia 1930" value="<?=form_value('dating_label',$piece)?>"></label><?php select_view('dating_certainty','Certeza',['unknown'=>'Sin determinar','estimated'=>'Aproximada','documented'=>'Documentada'],$piece,'unknown'); ?><label>Año desde<input type="number" name="year_from" min="-32768" max="32767" value="<?=form_value('year_from',$piece)?>"></label><label>Año hasta<input type="number" name="year_to" min="-32768" max="32767" value="<?=form_value('year_to',$piece)?>"></label></div><label>Medidas<input name="dimensions_label" maxlength="255" placeholder="Ej.: 25 × 18 × 12 cm" value="<?=form_value('dimensions_label',$piece)?>"></label><label>Estado de conservación<textarea name="condition_description" rows="3" maxlength="10000"><?=form_value('condition_description',$piece)?></textarea></label><details><summary>Procedencia pública</summary><label>Información que puede mostrarse al visitante<textarea name="provenance_public" rows="3" maxlength="10000"><?=form_value('provenance_public',$piece)?></textarea></label></details></section>
    <section class="card" data-category-container><h2>Datos de la categoría</h2><p class="muted" id="category-hint">Completá sólo los datos que tengas. Elegí una categoría para ver sus campos.</p><?php foreach ($categories as $cat): ?><fieldset data-fields-category="<?=$cat['id']?>"><legend><?=h($cat['name'])?></legend><div class="field-grid"><?php foreach ($fields as $field): if ($field['category_id']!=$cat['id']) continue; $value=$_POST['fields'][$cat['id']][$field['field_key']]??$values[$cat['id']][$field['field_key']]??''; if (!$field['active']&&$value==='') continue; ?><label><?=h($field['label'])?><input name="fields[<?=$cat['id']?>][<?=h($field['field_key'])?>]" value="<?=h($value)?>" maxlength="10000"></label><?php endforeach ?></div></fieldset><?php endforeach ?><label class="check muted"><input type="checkbox" name="confirm_category_removal" value="1" <?=!empty($_POST['confirm_category_removal'])?'checked':''?>>Confirmo eliminar datos específicos de las categorías que quite.</label></section>
    <section class="card" data-step="photos" data-step-title="Fotografías"><h2>Fotografías</h2><label class="upload">Agregar fotos<input id="photos" type="file" name="photos[]" multiple accept="image/jpeg,image/png,image/webp"><small>Hasta 12 por carga · JPG, PNG o WebP · 15 MB y 12 megapíxeles por foto.</small></label><p class="muted">Se guardan copias para la web. Conservá los originales aparte. Para publicar hace falta una portada.</p><div id="upload-preview" class="upload-preview" aria-live="polite"></div><div class="image-list"><?php foreach ($images as $image): $meta=$_POST['image_meta'][$image['id']]??$image; ?><article class="image-edit" data-image-id="<?=$image['id']?>"><img loading="lazy" src="<?=h(url('media',['id'=>$image['id'],'variant'=>'thumbnail']))?>" alt="<?=h($image['alt_text'])?>"><div><div class="order-controls"><span draggable="true" data-drag-handle>↕ Arrastrar</span><button type="button" data-move="up" aria-label="Subir foto">↑</button><button type="button" data-move="down" aria-label="Bajar foto">↓</button></div><label class="check"><input type="radio" name="cover" value="<?=$image['id']?>" <?=((string)($_POST['cover']??'')===(string)$image['id']||(!isset($_POST['cover'])&&$image['is_cover']))?'checked':''?>>Portada</label><div class="field-grid"><label>Orden<input type="number" name="image_meta[<?=$image['id']?>][position]" min="0" max="1000000" value="<?=h($meta['position'])?>"></label><label>Función<select name="image_meta[<?=$image['id']?>][role]"><?php foreach (IMAGE_ROLES as $key=>$label): ?><option value="<?=$key?>" <?=$meta['role']===$key?'selected':''?>><?=$label?></option><?php endforeach ?></select></label></div><label>Texto alternativo<input name="image_meta[<?=$image['id']?>][alt]" maxlength="500" value="<?=h($meta['alt']??$image['alt_text'])?>"></label><label>Epígrafe<textarea rows="2" maxlength="10000" name="image_meta[<?=$image['id']?>][caption]"><?=h($meta['caption']??'')?></textarea></label><button type="button" class="danger" data-remove-image="<?=$image['id']?>">Quitar foto al guardar</button></div></article><?php endforeach ?></div></section>
    <section class="card" data-step="internal" data-step-title="Gestión interna"><h2>Gestión interna</h2><p class="muted">Estos datos no aparecen en la ficha de presentación.</p><label>Ubicación física<input name="physical_location" maxlength="255" value="<?=form_value('physical_location',$piece)?>"></label><label>Notas internas<textarea name="internal_notes" rows="4" maxlength="10000"><?=form_value('internal_notes',$piece)?></textarea></label></section>
    <section class="card" data-step="publication" data-step-title="Publicación"><h2>Publicación y disponibilidad</h2><div class="field-grid"><?php select_view('publication_status','Publicación',PUBLICATION,$piece,'draft'); select_view('availability','Disponibilidad',AVAILABILITY,$piece,'not_for_sale'); ?></div><p class="muted">Los precios y el canal de contacto siguen pendientes.</p></section><div class="savebar"><span id="save-state" role="status">Guardá para conservar tus cambios.</span><button class="primary" type="submit" name="save" value="1">Guardar ficha</button></div></form><?php if ($id): ?><div class="record-actions"><form method="post" action="<?=h(url('duplicate',['id'=>$id]))?>"><?=csrf()?><label class="check"><input type="checkbox" name="with_images" value="1" checked>Incluir fotografías en la copia</label><button type="submit" data-confirm="Se duplicará la última versión guardada como borrador. Los cambios sin guardar no se copian. ¿Continuar?">Duplicar ficha guardada</button></form></div><form class="trash-action" method="post" action="<?=h(url('trash',['id'=>$id]))?>"><?=csrf()?><button class="danger" data-confirm="¿Enviar esta pieza a papelera? Podrás restaurarla después.">Enviar a papelera</button></form><?php endif ?><?php
}
function preview_view(int $id): void {
    $piece=get_piece($id); if ($piece['deleted_at']) throw new InvalidArgumentException('La pieza está en papelera.');
    $images=piece_images($id); usort($images,fn($a,$b)=>(int)$b['is_cover']<=>(int)$a['is_cover']);
    $fields=query('SELECT f.label,v.value_text FROM piece_field_values v JOIN category_fields f ON f.category_id=v.category_id AND f.field_key=v.field_key WHERE v.piece_id=? ORDER BY f.category_id,f.position',[$id])->fetchAll();
    ?><div class="notice">Previsualización privada · <?=PUBLICATION[$piece['publication_status']]?> · Muestra los datos guardados.</div><div class="page-heading"><a class="back" href="<?=h(url('edit',['id'=>$id]))?>">← Editar ficha</a></div><section class="preview-layout"><div class="gallery"><?php foreach ($images as $image): ?><figure><a href="<?=h(url('media',['id'=>$image['id'],'variant'=>'zoom']))?>" target="_blank" rel="noopener"><img src="<?=h(url('media',['id'=>$image['id'],'variant'=>'web']))?>" alt="<?=h($image['alt_text'])?>" loading="lazy"></a><?php if ($image['caption']): ?><figcaption><?=h($image['caption'])?></figcaption><?php endif ?></figure><?php endforeach ?><?php if (!$images): ?><div class="empty card">Todavía no hay fotos.</div><?php endif ?></div><article class="card preview-data"><span class="code"><?=h($piece['code'])?></span><h1><?=h($piece['title'])?></h1><span class="badge <?=$piece['availability']?>"><?=AVAILABILITY[$piece['availability']]?></span><?php if ($piece['dating_label']): ?><p><?=h($piece['dating_label'])?><?=$piece['dating_certainty']==='estimated'?' · Datación aproximada':''?></p><?php endif ?><p class="multiline"><?=h($piece['description'])?></p><dl><?php if ($piece['unit_type']==='set'): ?><dt>Conjunto</dt><dd><?=$piece['component_count']?h($piece['component_count']).' componentes':'Cantidad sin determinar'?></dd><?php endif ?><?php if ($piece['dimensions_label']): ?><dt>Medidas</dt><dd><?=h($piece['dimensions_label'])?></dd><?php endif ?><?php foreach ($fields as $f): ?><dt><?=h($f['label'])?></dt><dd><?=h($f['value_text'])?></dd><?php endforeach ?></dl><?php if ($piece['condition_description']): ?><h2>Conservación</h2><p class="multiline"><?=h($piece['condition_description'])?></p><?php endif ?><?php if ($piece['provenance_public']): ?><h2>Procedencia</h2><p class="multiline"><?=h($piece['provenance_public'])?></p><?php endif ?></article></section><?php
}
